{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "DailyWeatherForecast",
  "description": "A schema representing a daily weather forecast entry.",
  "type": "object",
  "properties": {
    "date": {
      "type": "string",
      "format": "date"
    },
    "high_temp": {
      "type": "number"
    },
    "low_temp": {
      "type": "number"
    },
    "condition": {
      "type": "string"
    },
    "humidity": {
      "type": "integer",
      "minimum": 0,
      "maximum": 100
    },
    "wind_speed": {
      "type": "number"
    },
    "icon_id": {
      "type": "string"
    }
  },
  "required": [
    "date",
    "high_temp",
    "low_temp",
    "condition"
  ]
}
```

